package com.vandorlabs.vehicle;

import io.netty.buffer.*;
import java.util.*;
import net.minecraft.util.math.BlockPos;

/** Real vehicle Packet codec, including unchanged ordinary STATE and append-only scalar tail. */
public final class VehicleArmMotionCodecChecks {
    private static int checks;
    private static void need(boolean v,String why){checks++;if(!v)throw new AssertionError("Arm STATE codec: "+why);}
    private static VehicleNetwork.Packet packet(int count,boolean joints){VehicleNetwork.Packet p=new VehicleNetwork.Packet(VehicleNetwork.STATE);p.entity=9;p.token=new UUID(3,4);p.sequence=23;p.serverTick=47;p.x=10.25;p.y=42;p.z=-19;p.dy=.125;p.speed=.3;p.yaw=-27;p.steering=3;if(joints){p.jointTopology=-42;p.jointAngles=new short[]{-7500,0,12,-19,7500,0};}if(count>0){List<VehicleArmMotionFrame.Arm> arms=new ArrayList<>();for(int i=0;i<count;i++)arms.add(new VehicleArmMotionFrame.Arm(new BlockPos(i,63,62),1099511627776L+i,i==0?0:i==count-1?1:i/(double)count,(i&1)!=0));p.armMotion=new VehicleArmMotionFrame(-741,arms);}return p;}
    private static byte[] bytes(VehicleNetwork.Packet p){ByteBuf b=Unpooled.buffer();try{p.toBytes(b);byte[] result=new byte[b.readableBytes()];b.getBytes(b.readerIndex(),result);return result;}finally{b.release();}}
    private static VehicleNetwork.Packet decode(byte[] data){ByteBuf b=Unpooled.wrappedBuffer(data);try{VehicleNetwork.Packet p=new VehicleNetwork.Packet();p.fromBytes(b);return p;}finally{b.release();}}
    private static byte[] changed(byte[] source,int at,long value,int length){byte[] out=source.clone();ByteBuf b=Unpooled.wrappedBuffer(out);try{if(length==1)b.setByte(at,(int)value);else if(length==2)b.setShort(at,(int)value);else b.setLong(at,value);return out;}finally{b.release();}}
    public static void main(String[] args){
        net.minecraft.init.Bootstrap.register();for(boolean joints:new boolean[]{false,true})for(int count:new int[]{0,1,2,32,64}){VehicleNetwork.Packet p=packet(count,joints);byte[] wire=bytes(p);need(wire.length==(joints?108:82)+(count==0?0:15+25*count),"exact unchanged legacy and bounded scalar tail byte count");VehicleNetwork.Packet decoded=decode(wire);need(decoded.valid&&decoded.entity==p.entity&&decoded.token.equals(p.token)&&decoded.serverTick==p.serverTick&&decoded.sequence==p.sequence&&decoded.x==p.x&&Arrays.equals(decoded.jointAngles,p.jointAngles)&&decoded.jointTopology==p.jointTopology,"ordinary fields/joints exact roundtrip");need(decoded.armMotion.arms.size()==count&&decoded.armMotion.encodedBytes()==p.armMotion.encodedBytes(),"optional phase count/size");for(int i=0;i<count;i++){VehicleArmMotionFrame.Arm a=p.armMotion.arms.get(i),b=decoded.armMotion.arms.get(i);need(a.root.equals(b.root)&&a.revision==b.revision&&Double.doubleToLongBits(a.progress)==Double.doubleToLongBits(b.progress)&&a.target==b.target,"phase record exact roundtrip");}need(Arrays.equals(wire,bytes(decoded)),"exact byte roundtrip");}
        byte[] good=bytes(packet(2,true));int tail=108,first=tail+15;
        need(!decode(changed(good,tail+4,2,1)).valid,"unknown version refuses");need(!decode(changed(good,tail+5,0,8)).valid,"missing layout identity refuses");for(int count:new int[]{0,3,65,65535})need(!decode(changed(good,tail+13,count,2)).valid,"count/missing record refuses before record allocation");need(!decode(changed(good,first,new BlockPos(-1,0,0).toLong(),8)).valid,"negative root refuses");need(!decode(changed(good,first,new BlockPos(64,0,0).toLong(),8)).valid,"out of structure root refuses");need(!decode(changed(good,first+8,-1,8)).valid,"negative revision refuses");for(double p:new double[]{Double.NaN,Double.POSITIVE_INFINITY,-.001,1.001})need(!decode(changed(good,first+16,Double.doubleToLongBits(p),8)).valid,"invalid progress refuses");need(!decode(changed(good,first+24,2,1)).valid,"reserved flags refuse");need(!decode(changed(good,first+25,new BlockPos(0,63,62).toLong(),8)).valid,"duplicate roots refuse");
        for(int length=0;length<good.length;length++)need(decode(Arrays.copyOf(good,length)).valid==(length==82||length==108),"only complete historical optional-tail boundaries remain valid length="+length);byte[] trailing=Arrays.copyOf(good,good.length+1);need(!decode(trailing).valid,"trailing byte refuses");byte[] armOnly=bytes(packet(1,false)),duplicate=Arrays.copyOf(armOnly,armOnly.length+armOnly.length-82);System.arraycopy(armOnly,82,duplicate,armOnly.length,armOnly.length-82);need(!decode(duplicate).valid,"duplicate tail refuses");
        VehicleNetwork.Packet reused=new VehicleNetwork.Packet();ByteBuf firstBuffer=Unpooled.wrappedBuffer(good),legacy=Unpooled.wrappedBuffer(bytes(packet(0,false)));try{reused.fromBytes(firstBuffer);need(reused.valid&&!reused.armMotion.arms.isEmpty(),"decode phase into reused object");reused.fromBytes(legacy);need(reused.valid&&reused.armMotion==VehicleArmMotionFrame.NONE&&reused.jointAngles.length==0,"legacy decode cannot retain previous phase records");}finally{firstBuffer.release();legacy.release();}
        System.out.println("Vehicle ARM1 codec PASS checks="+checks+" legacy82B/threeJoint108B unchanged; oneArm+40B/max64+1615B; exact roundtrip/truncation/version/roots/revision/ranges/duplicate/trailing bounds before allocation; runtime application separate");
    }
}
